insert into public.roles (key, name, description, scope_level, rank) values
  ('PRESIDENT_GENERAL', 'President General', 'Leads NCUDA as a whole. Delegates authority to regional and chapter leadership.', 'organization', 1),
  ('VICE_PRESIDENT_GENERAL', 'Vice President General', 'Deputises for the President General, with all of the President General''s powers.', 'organization', 2),
  ('SECRETARY_GENERAL', 'National Secretary General', 'Keeps the central records: general meetings, minutes, correspondence and documents.', 'organization', 3),
  ('CENTRAL_FINANCIAL_SECRETARY', 'National Financial Secretary', 'Keeps the central ledger (money received and spent by the central body), oversees all chapters'' records, and creates organisation-wide projects.', 'organization', 4),
  ('CENTRAL_TREASURER', 'Central Treasurer', 'Safeguards the central funds and reviews financial records across chapters.', 'organization', 5),
  ('REGIONAL_COORDINATOR', 'Regional Coordinator', 'Coordinates the chapters of a region on behalf of the central organisation.', 'region', 6),
  ('CHAPTER_PRESIDENT', 'Chapter President', 'Leads a chapter: enrols its members, appoints its officers, and runs its meetings and decisions.', 'chapter', 7),
  ('CHAPTER_VICE_PRESIDENT', 'Chapter Vice President', 'Deputises for the Chapter President, with all of the Chapter President''s powers.', 'chapter', 8),
  ('CHAPTER_SECRETARY', 'Chapter Secretary', 'Keeps the chapter’s records: meetings, attendance and minutes.', 'chapter', 9),
  ('CHAPTER_VICE_SECRETARY', 'Chapter Vice Secretary', 'Assists the Secretary with attendance and minutes.', 'chapter', 10),
  ('TREASURER', 'Treasurer', 'Safeguards the chapter’s funds and reviews financial records.', 'chapter', 11),
  ('FINANCIAL_SECRETARY', 'Financial Secretary', 'Keeps the chapter''s books: contributions, fines and the chapter''s spending.', 'chapter', 12),
  ('SOCIALS', 'Socials', 'Organises the chapter’s social and cultural life.', 'chapter', 13),
  ('SOCIALS_VICE', 'Socials Vice', 'Supports the Socials officer.', 'chapter', 14)
